  ('ai:ai-batch-02:433d3a73cab5','A2'::public.cefr_level,'reading','Look at the sign. When can you buy a book on Saturday?',array['between 9 a.m. and 5 p.m.','all day','between 10 a.m. and 2 p.m.','You can''t: the shop is closed.']::text[],'C','On Saturday the shop opens at 10:00 and closes at 14:00.',array['picture','reading','time']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,'image','samples/shop_hours.png','Bookshop opening hours'),
  ('ai:ai-batch-02:26f5d1c2eaf1','A2'::public.cefr_level,'reading','Look at the sign. On which day is the bookshop closed?',array['Saturday','Friday','Sunday','Monday']::text[],'C','The sign says Sunday: closed.',array['picture','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,'image','samples/shop_hours.png','Bookshop opening hours'),
  ('ai:ai-batch-02:44a3ffe203d6','A2'::public.cefr_level,'vocabulary','Watch the clock. What time is it at the end of the video?',array['It''s half past two.','It''s quarter past two.','It''s quarter to three.','It''s quarter past three.']::text[],'C','The long hand stops on 9 and the short hand is almost on 3: 2:45, quarter to three.',array['video','time']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,'video','samples/clock_2_to_quarter_to_3.mp4','A clock (7 seconds)'),
  ('ai:ai-batch-02:17cd8dfd2a68','A2'::public.cefr_level,'reading','Watch the video. What does Sara do after breakfast?',array['She goes to the gym.','She takes the bus to work.','She wakes up.','She has lunch with a friend.']::text[],'B','7:30 breakfast, then 8:00 the bus to work.',array['video','daily_routine']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,'video','samples/saras_day.mp4','Sara''s day (10 seconds)'),
  ('ai:ai-batch-02:f7b11ad72b3c','A2'::public.cefr_level,'reading','Watch the video. What time does Sara go to the gym?',array['at 6 p.m.','at 1 p.m.','at 7.30 a.m.','at 8 a.m.']::text[],'A','The last scene shows 18:00, which is 6 p.m.',array['video','time']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,'video','samples/saras_day.mp4','Sara''s day (10 seconds)'),
  ('ai:ai-batch-02:7218c2696e2b','B1'::public.cefr_level,'grammar','Choose the correct conditional sentence:',array['If I will see her, I''ll tell her.','If I saw her, I''ll tell her.','If I see her, I''ll tell her.','If I''ll see her, I tell her.']::text[],'C','First conditional: if + present simple, will + verb.',array['conditionals','correct_sentence']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:ad45b78db0d3','B1'::public.cefr_level,'grammar','Find the mistake: "I''m looking forward to meet you." Which word is wrong?',array['forward','meet','you','looking']::text[],'B','''Look forward to'' is followed by -ing: to meeting you.',array['gerunds','error_spotting']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:d807e1efe27e','B1'::public.cefr_level,'grammar','Find the mistake: "She has worked here since three years." Which word is wrong?',array['has','worked','since','here']::text[],'C','With a period of time we use ''for'': for three years.',array['present_perfect','error_spotting']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:dc11c419cfa9','B1'::public.cefr_level,'vocabulary','A: Do you mind if I open the window?  B: ___',array['No, I mind.','Yes, please open it.','Yes, I don''t mind.','No, not at all. Go ahead.']::text[],'D','''Do you mind…?'' = is it a problem? ''No, not at all'' gives permission.',array['dialogue','functions']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:f9f6ca70dcb8','B1'::public.cefr_level,'vocabulary','A: I failed my driving test again.  B: ___',array['Congratulations!','That''s a pity you passed.','Oh no, I''m sorry to hear that.','I''m glad to hear that.']::text[],'C','We show sympathy with ''I''m sorry to hear that.''',array['dialogue','functions']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:641bd2e27c2c','B1'::public.cefr_level,'grammar','The book ___ by millions of people since it came out.',array['is reading','has read','has been read','was reading']::text[],'C','Present perfect passive: has been + past participle.',array['passive','present_perfect']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:4cd358e66686','B1'::public.cefr_level,'grammar','He asked me if I ___ come to the party.',array['could','could I','can I','will I']::text[],'A','Reported questions use statement word order: if I could.',array['reported_speech']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:daff09d200b7','B1'::public.cefr_level,'grammar','You''d better ___ a coat; it''s freezing.',array['wear','to wear','wore','wearing']::text[],'A','''Had better'' is followed by the base form.',array['modals']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:f318176c2982','B1'::public.cefr_level,'grammar','I''m interested ___ learning photography.',array['on','for','in','about']::text[],'C','We say ''interested in''.',array['adjective_prepositions']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:b7e0ca946ecd','B1'::public.cefr_level,'grammar','Whether we go or not depends ___ the weather.',array['from','of','in','on']::text[],'D','We say ''depend on''.',array['verb_prepositions']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:3a2ceded277e','B1'::public.cefr_level,'vocabulary','Which word is closest in meaning to ''huge''?',array['tall','tiny','heavy','enormous']::text[],'D','Huge = enormous = very big.',array['synonyms']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
