  ('ai:ai-batch-02:c16aeb672e33','B1'::public.cefr_level,'vocabulary','Could you turn ___ the music a little? I''m trying to sleep.',array['over','into','down','up']::text[],'C','''Turn down'' = make quieter.',array['phrasal_verbs']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
