  ('ai:ai-batch-02:1169f0ebe1ae','B1'::public.cefr_level,'grammar','''I am tired,'' she said. Choose the correct reported sentence:',array['She said she was tired.','She said she is tired yesterday.','She said I was tired.','She told she was tired.']::text[],'A','In reported speech ''am'' usually becomes ''was''; ''tell'' needs an object.',array['reported_speech']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:541a0de588fb','B1'::public.cefr_level,'grammar','Which sentence uses the passive correctly?',array['The windows cleaned every week.','The windows are cleaned every week.','The windows are cleaning every week.','The windows is cleaned every week.']::text[],'B','Present simple passive: are + past participle.',array['passive']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:df76310a494b','B1'::public.cefr_level,'reading','What did the study find about using phones late at night?',array['It made students happier.','It helped students relax.','It was linked to less sleep.','It had no effect on sleep.']::text[],'C','They ''slept, on average, one hour less''.',array['reading']::text[],'draft','unreviewed','ai-draft:ai-batch-02','Many teenagers today spend more than six hours a day looking at screens. A recent study of 2,000 students found that those who used their phones late at night slept, on average, one hour less than those who did not. The researchers suggest that students should turn off their phones an hour before bed. They also found that students who did sport three times a week said they felt happier and less stressed.',null,null,null),
  ('ai:ai-batch-02:aa01e64fcc4e','B1'::public.cefr_level,'reading','What do the researchers recommend?',array['doing sport every day','sleeping one hour less','switching phones off an hour before going to bed','using phones for only six hours a day']::text[],'C','''Students should turn off their phones an hour before bed.''',array['reading']::text[],'draft','unreviewed','ai-draft:ai-batch-02','Many teenagers today spend more than six hours a day looking at screens. A recent study of 2,000 students found that those who used their phones late at night slept, on average, one hour less than those who did not. The researchers suggest that students should turn off their phones an hour before bed. They also found that students who did sport three times a week said they felt happier and less stressed.',null,null,null),
  ('ai:ai-batch-02:8e19c52569d5','B1'::public.cefr_level,'reading','How many students took part in the study?',array['2,000','6','200','20,000']::text[],'A','''A recent study of 2,000 students''.',array['reading','numbers']::text[],'draft','unreviewed','ai-draft:ai-batch-02','Many teenagers today spend more than six hours a day looking at screens. A recent study of 2,000 students found that those who used their phones late at night slept, on average, one hour less than those who did not. The researchers suggest that students should turn off their phones an hour before bed. They also found that students who did sport three times a week said they felt happier and less stressed.',null,null,null),
  ('ai:ai-batch-02:acb19bf3af4b','B1'::public.cefr_level,'reading','What will the volunteers do?',array['clean the streets','teach children','build a new park','plant trees in parks']::text[],'D','''Volunteers to plant trees in local parks''.',array['reading']::text[],'draft','unreviewed','ai-draft:ai-batch-02','VOLUNTEERS WANTED!
