  ('ai:ai-batch-02:530ea9f33e16','B2'::public.cefr_level,'grammar','Choose the correct sentence about a past regret:',array['I wish I had studied harder for the exam.','I wish I studied harder for the exam last year.','I wish I have studied harder for the exam.','I wish I would study harder for the exam yesterday.']::text[],'A','Regrets about the past: wish + past perfect.',array['wishes','correct_sentence']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:def97ab46ab5','B2'::public.cefr_level,'grammar','Find the mistake: "Despite of the rain, we enjoyed the trip." Which word is wrong?',array['rain','enjoyed','of','Despite']::text[],'C','''Despite'' is not followed by ''of'' (but ''in spite of'' is).',array['linkers','error_spotting']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:44aad09cb322','B2'::public.cefr_level,'grammar','Find the mistake: "The informations you gave me helped a lot." Which word is wrong?',array['gave','informations','lot','helped']::text[],'B','''Information'' is uncountable: no plural -s.',array['uncountable','error_spotting']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
