  ('ai:ai-batch-02:3f7eae53c35b','B2'::public.cefr_level,'grammar','Unless you ___ now, you''ll miss the train.',array['don''t leave','left','leave','will leave']::text[],'C','''Unless'' = if not, followed by a present verb.',array['conditionals']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:636bf53c4974','B2'::public.cefr_level,'grammar','The report needs ___ by Friday.',array['to finish','be finished','to be finished','finish']::text[],'C','Passive infinitive after ''need'': needs to be finished.',array['passive']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:20e4fe7b2bda','B2'::public.cefr_level,'vocabulary','Which word is closest in meaning to ''reluctant''?',array['relieved','careless','eager','unwilling']::text[],'D','Reluctant = not wanting to do something.',array['synonyms']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:8b3fc224a75f','B2'::public.cefr_level,'vocabulary','Which word is closest in meaning to ''reliable''?',array['dependable','flexible','relaxed','available']::text[],'A','Reliable = you can depend on it.',array['synonyms']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
  ('ai:ai-batch-02:3a859597b3c8','B2'::public.cefr_level,'vocabulary','The ___ of the new bridge took three years. (CONSTRUCT)',array['construction','constructive','constructor','constructed']::text[],'A','A noun is needed after ''the'': construction.',array['word_formation']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
