  ('ai:ai-batch-02:7f4d1c1a9aa4','B2'::public.cefr_level,'vocabulary','The company has ___ a profit for the first time in five years.',array['given','taken','done','made']::text[],'D','Collocation: make a profit.',array['collocations']::text[],'draft','unreviewed','ai-draft:ai-batch-02',null,null,null,null),
